<script setup>
import {ref,computed,watch} from 'vue';import DateInput from '../components/DateInput.vue';import BaseModal from '../components/BaseModal.vue';import {state,api,scope,useResource,notify} from '../lib/workspace';
import {can,allowedApi,writable} from '../lib/workspace';import {money,date,statusLabel} from '../lib/format';
const props=defineProps({area:{type:String,default:'accounting'}});
const allKinds={diary:'Diário Geral','consolidated-diary':'Diário Consolidado',ledger:'Razão','trial-balance':'Balancete','cost-centers':'Movimentos por centro de custo','balance-sheet':'Balanço patrimonial','income-statement':'Demonstração do resultado','fiscal-book':'Livro auxiliar fiscal','fiscal-documents':'Documentos fiscais','fiscal-entries':'Livro auxiliar de entradas','fiscal-outputs':'Livro auxiliar de saídas','fiscal-items':'Itens escriturados','fiscal-operations':'Operações por CFOP','fiscal-participants':'Operações por participante','fiscal-classifications':'Itens por NCM e CFOP','fiscal-taxes':'Bases e tributos declarados','fiscal-inconsistencies':'Pendências de conferência','fiscal-assessments':'Livro auxiliar de apuração',financial:'Títulos por vencimento','cash-flow':'Caixa realizado',partners:'Conciliação de clientes e fornecedores'};
const kinds=Object.fromEntries(Object.entries(allKinds).filter(([k])=>props.area==='fiscal'?k.startsWith('fiscal-'):props.area==='financial'?['financial','cash-flow','partners'].includes(k):!k.startsWith('fiscal-')&&!['financial','cash-flow','partners'].includes(k)));
const routine=props.area+'.reports';
const cfop=ref(''),ncm=ref('');
const kind=ref(props.area==='fiscal'?'fiscal-documents':props.area==='financial'?'financial':'trial-balance'),start=ref(''),end=ref(''),account=ref(''),center=ref(''),query=ref(''),status=ref(''),direction=ref(''),page=ref(1),result=ref(null),busy=ref(false),error=ref(''),origin=ref(null);let sequence=0;
const {data}=useResource(async()=>{if(!state.companyId)return {accounts:[],centers:[]};const [accounts,centers]=await Promise.all([allowedApi('accounting.accounts',scope('/accounts')),allowedApi('accounting.cost_centers',scope('/cost-centers'))]);return {accounts,centers};},{accounts:[],centers:[]});
watch(()=>[state.companyId,state.period],()=>{sequence++;result.value=null;account.value='';center.value='';start.value=state.period+'-01';const [y,m]=state.period.split('-').map(Number);end.value=new Date(Date.UTC(y,m,0)).toISOString().slice(0,10);},{immediate:true});
const accounting=computed(()=>['diary','consolidated-diary','ledger','trial-balance','cost-centers','balance-sheet','income-statement'].includes(kind.value));
const searchable=computed(()=>kind.value.startsWith('fiscal-')&&kind.value!=='fiscal-assessments'||['diary','ledger','fiscal-book','financial','cash-flow','partners'].includes(kind.value));
const statuses=computed(()=>kind.value.startsWith('fiscal-')?['pending','reviewed','booked']:['financial','partners'].includes(kind.value)?['open','partial','settled','cancelled','renegotiated']:[]);
const originRecord=computed(()=>origin.value?.data?.document&&typeof origin.value.data.document==='object'?origin.value.data.document:origin.value?.data);
watch(kind,()=>{status.value='';direction.value='';query.value='';account.value='';center.value='';});
const labels={item:'Item',ncm:'NCM',unit:'Unidade',quantity:'Quantidade',item_total_cents:'Total dos itens',ledger_id:'Apuração',assessment_id:'Memória',period:'Competência',tax:'Tributo',opening_credit_cents:'Crédito anterior',payable_cents:'A recolher',carry_credit_cents:'Crédito a transportar',message:'Diagnóstico',code:'Código',document_ids:'Documentos de origem',items:'Itens',occurrences:'Ocorrências',date:'Data',journal_id:'Lançamento',number:'Número',document:'Documento',history:'Histórico',account_id:'Conta ID',access_code:'Acesso',classifier:'Classificação',account_name:'Conta',nature:'Natureza',report_group:'Grupo',cost_center_id:'Centro ID',cost_center_name:'Centro de custo',debit_cents:'Débitos',credit_cents:'Créditos',opening_cents:'Saldo inicial',balance_cents:'Saldo',closing_cents:'Saldo final',journal_ids:'Lançamentos de origem',result_cents:'Resultado',document_id:'Documento ID',series:'Série',model:'Modelo',partner_name:'Participante',direction:'Operação',cfop:'CFOP',total_cents:'Total',status:'Situação',title_id:'Título',kind:'Tipo',description:'Descrição',issue_date:'Emissão',due_date:'Vencimento',amount_cents:'Valor original',paid_cents:'Principal baixado',cash_cents:'Caixa',settlement_id:'Baixa',event:'Evento',consistent:'Consistente',settlement_ids:'Baixas',bank_ids:'Movimentos bancários',assets_cents:'Ativo',liabilities_cents:'Passivo',equity_cents:'Patrimônio líquido',unclosed_result_cents:'Resultado não encerrado',difference_cents:'Diferença',documents:'Documentos'};
for(const tax of ['icms','ipi','iss','pis','cofins','ibs','cbs']){labels[tax+'_cents']=tax.toUpperCase()+' declarado';labels[tax+'_base_cents']='Base '+tax.toUpperCase();labels[tax+'_informed_documents']='Documentos com '+tax.toUpperCase();}
const columns=computed(()=>[...new Set((result.value?.rows||[]).flatMap(Object.keys))].filter(k=>!['nature','account_id','cost_center_id'].includes(k)));const visible=computed(()=>(result.value?.rows||[]).slice((page.value-1)*50,page.value*50));
function parameters(){const p=new URLSearchParams({cfop:cfop.value,ncm:ncm.value,start:start.value,end:end.value,query:searchable.value?query.value:'',status:statuses.value.length?status.value:'',direction:!accounting.value?direction.value:''});if(accounting.value&&account.value)p.set('account_id',account.value);if(accounting.value&&center.value)p.set('cost_center_id',center.value);return p;}
async function run(){const seq=++sequence;busy.value=true;error.value='';try{const cid=state.companyId;const url=scope(`/business-reports/${kind.value}?${parameters()}`,cid);const r=await api(url);if(seq===sequence){result.value={...r,url};page.value=1;}}catch(e){if(seq===sequence)error.value=e.message;}finally{if(seq===sequence)busy.value=false;}}
function display(k,v){if(v===null||v===undefined)return '—';if(k.endsWith('_cents'))return money(v);if(k==='date'||k.endsWith('_date'))return date(v);if(Array.isArray(v))return v.map(x=>'#'+x).join(', ');if(typeof v==='boolean')return v?'Sim':'Não';if(['status','kind','direction'].includes(k))return statusLabel(v);if(k==='report_group')return ({asset:'Ativo',liability:'Passivo',equity:'Patrimônio líquido',revenue:'Receita',expense:'Despesa'})[v]||'Não classificado';return v??'—';}
async function showOrigin(row,key){try{if(key==='ledger_id'){origin.value={type:'Apuração',data:await api(scope(`/tax-ledgers/${row[key]}/report`,result.value.company_id))};return;}if(key==='journal_id')origin.value={type:'Lançamento',data:await api(scope(`/journals/${row[key]}`,result.value.company_id))};else if(key==='document_id')origin.value={type:'Documento',data:await api(scope(`/documents/${row[key]}/trace`,result.value.company_id))};else if(key==='title_id'){const t=await api(scope('/titles',result.value.company_id));origin.value={type:'Título',data:t.find(t=>t.id===row[key])};}}catch(e){notify(e.message,'error');}}
async function printReport(){try{const r=await fetch(`/api${result.value.url}&format=pdf&purpose=print`,{credentials:'same-origin'});if(!r.ok)throw new Error((await r.json()).detail||'Impressão não autorizada.');window.print();}catch(e){notify(e.message,'error');}}
</script>
<template><div class="view reports-view"><header class="view-heading"><div><div class="eyebrow">LIVROS E DEMONSTRATIVOS</div><h1>Livros e relatórios</h1><p>Filtros explícitos, valores conferíveis e acesso à origem.</p></div></header><form class="panel report-controls" @submit.prevent="run"><div class="form-grid three"><label>Relatório<select v-model="kind"><option v-for="(label,key) in kinds" :value="key" :key="key">{{label}}</option></select></label><label>Data inicial<DateInput v-model="start" required/></label><label>Data final<DateInput v-model="end" required/></label><label>Conta<select v-model="account" :disabled="!accounting"><option value="">Todas</option><option v-for="a in data.accounts" :value="a.id" :key="a.id">{{a.access_code}} · {{a.name}}</option></select></label><label>Centro de custo<select v-model="center" :disabled="!accounting"><option value="">Todos</option><option v-for="c in data.centers" :value="c.id" :key="c.id">{{c.code}} · {{c.name}}</option></select></label><label>Documento, participante ou histórico<input v-model="query" :disabled="!searchable"/></label><label>Situação<select v-model="status" :disabled="!statuses.length"><option value="">Todas</option><option v-for="k in statuses" :key="k" :value="k">{{statusLabel(k)}}</option></select></label><label>Operação<select v-model="direction" :disabled="accounting"><option value="">Todas</option><template v-if="kind.startsWith('fiscal-')"><option value="incoming">Entrada fiscal</option><option value="outgoing">Saída fiscal</option></template><template v-else><option value="payable">A pagar</option><option value="receivable">A receber</option></template></select></label><template v-if="area==='fiscal'"><label>CFOP<input v-model="cfop" maxlength="4" :disabled="kind==='fiscal-assessments'"/></label><label>NCM<input v-model="ncm" maxlength="8" :disabled="kind==='fiscal-assessments'"/></label></template><button class="button primary" :disabled="busy">{{busy?'Consultando…':'Gerar relatório'}}</button></div></form><p v-if="error" class="message error" role="alert">{{error}}</p><section v-if="result" class="panel report-output"><header class="panel-heading"><div><h2>{{result.title||kinds[result.kind]}}</h2><p>{{result.company_name}} · {{date(result.start)}} a {{date(result.end)}}</p></div><div class="actions no-print"><a class="button outline" v-allow="[routine,'export']" :href="`/api${result.url}&format=csv`" download>Exportar CSV</a><a v-allow="[routine,'export']" class="button outline" :href="`/api${result.url}&format=xlsx`" download>Excel</a><a v-allow="[routine,'export']" class="button outline" :href="`/api${result.url}&format=pdf`" download>PDF</a><button class="button" v-allow="[routine,'print']" @click="printReport">Imprimir / PDF</button></div></header><p class="report-note">{{result.scope_note}}</p><div class="summary-strip"><div v-for="(value,key) in result.totals" :key="key"><span>{{labels[key]||key}}</span><strong>{{display(key,value)}}</strong></div></div><div class="table-scroll"><table><thead><tr><th v-for="key in columns" :key="key">{{labels[key]||key}}</th></tr></thead><tbody><tr v-for="(r,i) in result.rows" v-show="i>=(page-1)*50&&i<page*50" :key="i"><td v-for="key in columns" :key="key" :class="{'right money':key.endsWith('_cents')}"><button v-if="['journal_id','document_id','title_id','ledger_id'].includes(key)&&r[key]" class="text-button" @click="showOrigin(r,key)">#{{r[key]}}</button><span v-else-if="key==='journal_ids'" class="actions"><button v-for="id in r[key]" :key="id" class="text-button" @click="showOrigin({journal_id:id},'journal_id')">#{{id}}</button></span><span v-else>{{display(key,r[key])}}</span></td></tr></tbody></table></div><footer class="table-footer no-print"><span>{{result.rows.length}} linhas · página {{page}} · totais abrangem todas as linhas</span><div class="actions"><button class="button small" @click="page--" :disabled="page===1">Anterior</button><button class="button small" @click="page++" :disabled="page*50>=result.rows.length">Próxima</button></div></footer><p v-if="result.rows.length>50" class="message subtle no-print">Impressão e CSV incluem todas as linhas.</p></section><BaseModal v-if="origin" :title="origin.type+' de origem'" wide @close="origin=null"><div v-if="originRecord"><template v-if="origin.type==='Apuração'"><p>{{origin.data.scope_note}}</p><a v-allow="['fiscal.assessments','export']" class="button" :href="`/api${scope(`/tax-ledgers/${origin.data.ledger_id}/report`)}?format=pdf`" download>PDF da memória</a><pre>{{JSON.stringify(origin.data.totals,null,2)}}</pre></template><dl class="origin-summary"><dt>Documento</dt><dd>{{originRecord.number||originRecord.document||'—'}}</dd><dt>Data</dt><dd>{{date(originRecord.date||originRecord.posting_date||originRecord.issue_date)}}</dd><dt>Histórico / participante</dt><dd>{{originRecord.history||originRecord.description||originRecord.partner_name}}</dd><dt>Valor</dt><dd>{{money(originRecord.total_cents??originRecord.amount_cents)}}</dd></dl><div v-if="originRecord.lines" class="table-scroll"><table><thead><tr><th>Conta</th><th>Centro</th><th>Débito</th><th>Crédito</th></tr></thead><tbody><tr v-for="line in originRecord.lines" :key="line.id"><td>{{line.access_code}} · {{line.account_name}}</td><td>{{line.cost_center_name||'—'}}</td><td>{{money(line.debit_cents)}}</td><td>{{money(line.credit_cents)}}</td></tr></tbody></table></div><div v-if="originRecord.settlements" class="table-scroll"><p>Saldo atual: <strong>{{money(originRecord.balance_cents)}}</strong></p><table><thead><tr><th>Baixa</th><th>Principal</th><th>Caixa</th><th>Situação</th></tr></thead><tbody><tr v-for="s in originRecord.settlements" :key="s.id"><td>{{date(s.date)}}</td><td>{{money(s.amount_cents)}}</td><td>{{money(s.cash_cents)}}</td><td>{{s.reversed_at?'Estornada':'Ativa'}}</td></tr></tbody></table></div><div v-if="origin.data.titles" class="table-scroll"><table><thead><tr><th>Título</th><th>Vencimento</th><th>Valor</th><th>Saldo</th></tr></thead><tbody><tr v-for="t in origin.data.titles" :key="t.id"><td>{{t.description}}</td><td>{{date(t.due_date)}}</td><td>{{money(t.amount_cents)}}</td><td>{{money(t.balance_cents)}}</td></tr></tbody></table></div></div><template #footer><button class="button" @click="origin=null">Fechar</button></template></BaseModal></div></template>
